// Ephemeral review probes. These assertions describe observations on the frozen
// baseline, not the desired regression contract. No repository file is edited.
func TestFullReviewDailyLoadIsolation(t *testing.T) {
 ms, e := analysis.TrainingState(context.Background(), analysis.StateInput{From:"2026-10-29",Through:"2026-10-29",Timezone:"Asia/Shanghai",Loads:[]analysis.Load{{WorkoutID:"old",RunID:"old",Day:"2026-10-28",Value:nil},{WorkoutID:"today",RunID:"today",Day:"2026-10-29",Value:analysis.Ptr(100)}}})
 if e!=nil {t.Fatal(e)}
 dailyNil,fitnessNil:=false,false
 for _,m:=range ms {if m.Name=="daily_load" {dailyNil=m.Value==nil};if m.Name=="fitness" {fitnessNil=m.Value==nil}}
 if !dailyNil||!fitnessNil {t.Fatal("baseline observation changed")}
 t.Log("REVIEW_OBSERVATION daily_load_null=true although current-day input known; fitness_null=true correctly")
}
func TestFullReviewOverrideScheduleTransition(t *testing.T) {
 f:=setup(t);ctx:=context.Background();cfg:=trainingConfig()
 p,e:=f.s.CreateTrainingPlan(ctx,f.p,training.CreateRequest{CommandID:syncing.NewID(),PlanID:syncing.NewID(),Config:cfg});if e!=nil {t.Fatal(e)}
 runTraining(t,f);p,e=f.s.TrainingPlan(ctx,f.p,p.ID);if e!=nil{t.Fatal(e)}
 var target training.Session
 for _,s:=range p.Effective.Sessions {if s.Slot==9 {target=s}}
 if target.Type!="INTERVAL"||target.DurationS!=2880 {t.Fatal("unexpected fixture")}
 editTraining(t,f,p,target.ID,"distanceM",0,0)
 cfg.AvailableDays=[]int{1,2,3,5,7}
 _,e=f.s.ChangeTrainingPlan(ctx,f.p,p.ID,training.ChangeRequest{CommandID:syncing.NewID(),Operation:"update_config",ExpectedConfigRevision:1,Config:&cfg});if e!=nil{t.Fatal(e)}
 l:=claimTraining(t,f);jobs.Process(ctx,f.s,l,analysisLog)
 latest,e:=f.s.TrainingPlan(ctx,f.p,p.ID);if e!=nil{t.Fatal(e)}
 if latest.ConfigRevision!=2||latest.GenerationState!="failed"||latest.LastErrorCode!="invalid_training_input"||latest.Effective.BaseID!=p.Effective.BaseID||latest.Effective.OverrideRevision!=1||sessionID(latest.Effective.Base,target.ID).DistanceM!=0 {t.Fatalf("unexpected observation status=%s code=%s",latest.GenerationState,latest.LastErrorCode)}
 t.Log("REVIEW_OBSERVATION valid zero-distance interval override + accepted schedule update => invalid_training_input, new Base not published; old Effective and override retained")
}
func TestFullReviewTrainingJSONDrift(t *testing.T) {
 cases:=[]string{"missing_expected_revision","case_variant","duplicate_key","null_notes"}
 for _,name:=range cases {t.Run(name,func(t *testing.T){
 f,p:=trainingFixture(t);id:=p.Effective.Sessions[0].ID
 body:=map[string]any{"commandID":syncing.NewID(),"overrideID":syncing.NewID(),"sessionID":id,"operation":"edit","path":"distanceM","value":7000,"expectedOverrideRevision":0}
 if name=="missing_expected_revision"{delete(body,"expectedOverrideRevision")}
 if name=="case_variant"{body["CommandID"]=body["commandID"];delete(body,"commandID")}
 if name=="null_notes"{body["operation"]="add";sid:=syncing.NewID();body["sessionID"]=sid;delete(body,"path");delete(body,"value");body["session"]=map[string]any{"sessionID":sid,"date":p.Effective.Sessions[0].Date,"type":"EASY","distanceM":1000,"notes":nil}}
 b,_:=json.Marshal(body);if name=="duplicate_key"{b=append([]byte(`{"value":6000,`),b[1:]...)}
 h:=httpapi.New(f.s,analysisLog);r:=httptest.NewRequest("POST","/v2/training/plans/"+p.ID+"/overrides",bytes.NewReader(b));r.Header.Set("Authorization","Bearer "+f.enrollment.Token);r.Header.Set("Content-Type","application/json");w:=httptest.NewRecorder();h.ServeHTTP(w,r)
 if w.Code!=200 {t.Fatalf("observation changed: %d",w.Code)}
 t.Logf("REVIEW_OBSERVATION invalid schema case=%s accepted_http=200",name)
 })}
}
func TestFullReviewTrainingQueryBound(t *testing.T) {
 f:=setup(t);seedAnalysisHistory(t,f,1825);ctx:=context.Background()
 if _,e:=f.s.Pool.Exec(ctx,"ANALYZE workouts; ANALYZE analysis_publications; ANALYZE analysis_results; ANALYZE dirty_scopes; ANALYZE analysis_runs");e!=nil {t.Fatal(e)}
 var raw []byte
 if e:=f.s.Pool.QueryRow(ctx,"EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) "+postgres.TrainingWorkoutsSQL,f.p.DatasetID,"Asia/Shanghai","",time.Now().In(time.FixedZone("UTC+8",8*3600)).Format("2006-01-02")).Scan(&raw);e!=nil{t.Fatal(e)}
 var plan any;if e:=json.Unmarshal(raw,&plan);e!=nil{t.Fatal(e)}
 t.Log("REVIEW_PLAN="+string(raw))
}
func TestFullReviewHistoryBytes(t *testing.T) {
 f:=setup(t);ctx:=context.Background();cfg:=trainingConfig();cfg.Weeks=16
 p,e:=f.s.CreateTrainingPlan(ctx,f.p,training.CreateRequest{CommandID:syncing.NewID(),PlanID:syncing.NewID(),Config:cfg});if e!=nil{t.Fatal(e)};runTraining(t,f)
 for i:=0;i<49;i++ {recalcTraining(t,f,p);runTraining(t,f)}
 history,e:=f.s.TrainingHistory(ctx,f.p,p.ID,0,50);if e!=nil{t.Fatal(e)};b,e:=json.Marshal(history);if e!=nil{t.Fatal(e)}
 t.Logf("REVIEW_OBSERVATION history_versions=%d json_bytes=%d swift_response_limit=1048576",len(history.Versions),len(b))
 if len(b)<=1048576 {t.Fatal("baseline payload not above client limit")}
}

func TestFullReviewAuditBytes(t *testing.T) {
 f,p:=trainingFixture(t);ctx:=context.Background();sid:=p.Effective.Sessions[0].ID
 for i:=0;i<256;i++ { editTraining(t,f,p,sid,"notes",strings.Repeat("x",2000),int64(i)) }
 latest,e:=f.s.TrainingPlan(ctx,f.p,p.ID);if e!=nil{t.Fatal(e)}
 audit,e:=f.s.TrainingAudit(ctx,f.p,p.ID,latest.Effective.ID);if e!=nil{t.Fatal(e)}
 b,e:=json.Marshal(audit);if e!=nil{t.Fatal(e)}
 if len(b)<=1048576{t.Fatal("baseline audit below limit")}
 t.Logf("REVIEW_OBSERVATION actual_P6_audit_endpoint_override_count=%d json_bytes=%d swift_response_limit=1048576",len(audit.Overrides),len(b))
}
func TestFullReviewEqualRouteTimestamp(t *testing.T) {
 f:=setup(t);ctx:=context.Background();workoutStream(t,f)
 start:=time.Now().UTC().Add(-time.Hour).Truncate(time.Second);w:=workoutAt(start,60);f.commit(t,[]syncing.Event{w},1,nil);runOne(t,f,"analysis.workout")
 if _,e:=f.s.CurrentWorkoutAnalysis(ctx,f.p,w.UUID);e!=nil{t.Fatal(e)}
 route:=syncing.NewID();registerTestRoute(t,f,w.UUID,route,start,start.Add(2*time.Second),1,3)
 points:=testRoutePoints(start,3,0);points[1].RecordedAtUs=points[0].RecordedAtUs
 uploadTestRouteChunk(t,f,route,0,points);manifest,payload:=routeStateChains(t,f,route);sealTestRoute(t,f,route,1,3,manifest,payload)
 l:=claimAnalysis(t,f,"analysis.workout");jobs.Process(ctx,f.s,l,analysisLog)
 var state,code string;if e:=f.s.Pool.QueryRow(ctx,"SELECT state,COALESCE(last_error_code,'') FROM jobs WHERE id=$1",l.ID).Scan(&state,&code);e!=nil{t.Fatal(e)}
 if state!="failed"||code!="analysis_invalid_input"{t.Fatalf("changed observation: %s %s",state,code)}
 if _,e:=f.s.CurrentWorkoutAnalysis(ctx,f.p,w.UUID);e==nil{t.Fatal("expected hidden dirty publication")}
 t.Log("REVIEW_OBSERVATION route_with_equal_adjacent_timestamp accepted_and_sealed=true; workout_job=failed; error=analysis_invalid_input; previous_current_hidden=true")
}
